package com.starlight.greetings.web; import com.starlight.greetings.application.AdminLoginService; import java.util.Map; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/auth") public class AdminAuthController {private final AdminLoginService login;public AdminAuthController(AdminLoginService login){this.login=login;}@PostMapping("/login") public ResponseEntity<ApiEnvelope<Map<String,Object>>> signIn(@RequestBody Map<String,String> body){SignupResult r=login.login(body.get("nickname"),body.get("password"),body.get("totp"));return ResponseEntity.ok().header(HttpHeaders.SET_COOKIE,"star_session_dev="+r.sessionToken()+"; Path=/; HttpOnly; SameSite=Lax; Max-Age=43200").body(ApiEnvelope.of(Map.of("user",Map.of("id",r.id(),"nickname",r.nickname(),"role","admin"),"csrfToken",r.csrfToken())));}}
